import{_ as s,o as t,c as e,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"PhysicalAgent: Towards General Cognitive Robotics with Foundation World Models","description":"","frontmatter":{"title":"PhysicalAgent: Towards General Cognitive Robotics with Foundation World Models","arxiv":"2509.13903","date":"2025-09-17","authors":"Artem Lykov, Jeffrin Sam, Hung Khang Nguyen, Vladislav Kozlovskiy, Yara Mahmoud, Valerii Serpiva, Miguel Altamirano Cabrera, Mikhail Konenkov, Dzmitry Tsetserukou","categories":"cs.RO","topics":"物理感知视频生成, 具身智能体, 闭环执行","outline":[2,2]},"headers":[],"relativePath":"papers/2509.13903.md","filePath":"papers/2509.13903.md","lastUpdated":null}'),o={name:"papers/2509.13903.md"};function r(l,a,i,p,c,u){return t(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="physicalagent-towards-general-cognitive-robotics-with-foundation-world-models" tabindex="-1">PhysicalAgent: Towards General Cognitive Robotics with Foundation World Models <a class="header-anchor" href="#physicalagent-towards-general-cognitive-robotics-with-foundation-world-models" aria-label="Permalink to &quot;PhysicalAgent: Towards General Cognitive Robotics with Foundation World Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2509.13903" target="_blank" rel="noreferrer">2509.13903</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-09-17</td></tr><tr><td><strong>作者</strong></td><td>Artem Lykov, Jeffrin Sam, Hung Khang Nguyen, Vladislav Kozlovskiy, Yara Mahmoud, Valerii Serpiva, Miguel Altamirano Cabrera, Mikhail Konenkov, Dzmitry Tsetserukou</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把现成的图生视频大模型当成免训练的 world model 生成动作视频，只用一个轻量 pose 回归器把视频翻译成关节指令，再用 VLM 判定成败反复重试，把首次成功率 20–30% 抬到 80%。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要解决的是&quot;通用认知机器人&quot;的部署经济学问题：怎样让同一套高层推理与动作生成流水线，在不同本体、不同场景、不同任务之间迁移，而不需要每换一个机器人就重新收集数据、重新微调一个大模型。</p><p>现状是 RT-1/RT-2、OpenVLA、GR00T N1 这类 vision-language-action 模型把感知、推理、控制耦合成一个 monolithic policy。它在训练分布内表现好，但换一个机器人、换一个环境就要重新 fine-tune，而 fine-tune 需要该本体上的大规模示教数据。论文的立场是：把&quot;想象动作长什么样&quot;这件事外包给通用的图生视频基础模型，本体相关的部分压缩成一个只需几千条样本的轻量适配器。作者报告这个适配器的训练集约 10,000 条样本、采集耗时约 30 分钟。如果这条路走得通，新机器人的接入成本就从&quot;收集示教数据 + 微调 VLA&quot;降到&quot;半小时采集 + 训一个梯度提升回归器&quot;。</p><p>第二个被论文摆到台面上的问题更有意思：单次执行本来就不可靠。作者在物理平台上实测首次尝试成功率只有 20–30%，但通过 VLM 监督的迭代重规划，最终成功率能到 80%。这把讨论从&quot;怎么让 policy 一次做对&quot;转向&quot;怎么设计一个允许失败并能恢复的执行回路&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文点名了三条线。SayCan 用 LLM 打分把指令落到可执行技能上，但技能库本身要预先训练好；RT-1/RT-2、PaLM-E 走端到端 tokenize action 的路线，把 web 知识迁移到控制，代价是 policy 把高层推理和低层控制纠缠在一起，数据饥渴且难以跨本体复用；CognitiveOS 走模块化多智能体路线，但没有把动作生成本身交给基础模型。</p><p>对本文最关键的对照是 DreamGen。DreamGen 同样用 world model 合成轨迹来驱动机器人学习，但它依赖 Cosmos Predict 这类在精心配对的 robot–scene 数据上训练的专用预测模型。论文的批评很具体：这种专用性既限制了 out-of-distribution 泛化，又增加了部署时的工程负担——每接入一个新场景就要重新准备配对数据。PhysicalAgent 的反命题是，通用的 image→video 基础模型（实验里用 Wan 2.2 Image-to-Video Fast）本身已经从 web 规模数据里学到足够的接触事件与物体动力学先验，不需要机器人专用训练。</p><p>至于视觉推理，论文承认 VLM 已被广泛用于任务分解和 affordance 检测，但多数系统把 VLM 当作一次性的 open-loop planner。本文的差异在于把 VLM 放进闭环，每一步执行后都重新调用它做判定。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个观察：视频生成模型在 API 化之后，能力升级的速度远快于任何单个实验室能自己训练的机器人专用模型。如果机器人系统的核心先验来自一个可替换的 API，那么每次新模型发布（Seedance、Veo 2、Ray2、Wan 2.2），系统能力就自动提升，而不需要重训任何下游模块。这是一个关于工程杠杆的判断，不是关于算法优越性的判断。</p><p>第二步是问：视频到底能不能当动作用？作者的推理是，文生视频模型被训练成把文本指令对齐到视觉输出，这在结构上类似人在执行前先&quot;想象&quot;一遍动作。而且视频是人和机器都能读的中间表示，可以在执行前被 verifier 检查安全性。这两点让视频比直接输出扭矩或末端位姿更适合做中间层。</p><p>第三步是把剩余的本体相关部分尽量压小。既然视频里已经画出了机器人各关节应该在哪，那么只需要一个 2D 关键点检测器加一个回归器，就能把像素位置映射回关节角。这个子问题是有监督的、低维的、数据便宜的——机器人自己运动时同步记录关节角和相机帧就能自动标注。</p><p>第四步来自失败观察：单次生成的视频经常不可执行。既然 VLM 已经在流水线里，就顺手让它在执行前后各看一眼图像，判断&quot;继续 / 重试 / 回到高层规划&quot;。迭代因此不是事后补丁，而是这套架构的必然产物。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>不要让机器人学&quot;怎么动&quot;，让它学&quot;怎么把别人想象出来的动作抄下来&quot;。视频生成模型已经在网络视频里见过成千上万次开抽屉、递物体、擦液体，它对这些动作的时空结构有先验；机器人缺的只是&quot;把画面里的手臂位置翻译成自己的关节角&quot;，而这是一个 40 维特征到关节指令的普通回归问题。再加上一句：既然想象出来的动作大概率第一次不对，那就允许它错，让 VLM 看着结果决定要不要再想一次。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以论文里的 &quot;Lift the baking tray&quot;（抬起烤盘）为例，走一遍 Perceive → Plan → Reason → Act：</p><ul><li><strong>感知与分解</strong>。VLM（实现中用 Gemini Pro Flash，论文强调 GPT-4o/Claude-3.5/QwenVL 同样可用）接收当前相机帧和自然语言指令，把任务拆成原子技能序列，例如&quot;抓住烤盘左沿&quot;&quot;抓住右沿&quot;&quot;同步抬起&quot;。</li><li><strong>上下文化提示</strong>。对每个子任务，VLM 生成一段带约束的场景描述，说明相关物体、空间关系、物理约束和本体 affordance。这段文本连同当前帧一起作为 image→video 模型的条件。</li><li><strong>动作生成</strong>。图生视频基础模型（Wan 2.2 I2V Fast）从&quot;当前帧 + 描述&quot;合成一段短视频，画面里就是机器人执行该子任务的过程。这一步完全不涉及任何机器人专用训练。</li><li><strong>视频到控制</strong>。用微调过的 YOLO11-Pose 在每一帧上检测机器人关键点。双臂机械臂上跟踪 14 个关键点（每臂 6 关节 + 1 夹爪），得到 28 维坐标，再补上 12 个关节间连杆长度，构成 40 维特征。遮挡导致的缺失关键点用均值填补。特征送进 <code>MultiOutputRegressor</code> 包裹的 <code>HistGradientBoostingRegressor</code>（max_iter=500，lr=0.1，min_samples_leaf=20，early stopping）回归出关节指令。论文报告多数关节的平均绝对误差低于 0.1，运动范围大的关节（如 J7）误差更大。</li><li><strong>执行与判定</strong>。机器人执行完这一步后，VLM 看&quot;执行前 + 执行后&quot;两张图，输出三选一：继续、重试当前动作、回到高层重新规划。不可恢复的失败（物体掉到够不着的地方）或达到 10 次尝试上限则终止。</li></ul><p>适配器训练数据的采集方式很朴素：机器人自己运动，同步记录相机帧、当前关节位置，以及由相机内参和逆运动学投影出的 2D 关键点。YOLO11-Pose 微调 150 epoch，batch 8，图像尺寸 1280，冻结 backbone 前 10 层，在一张 RTX 4090 上完成。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。唯一的统计量是实验中的单因素方差分析：方法对成功率的主效应为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord">4</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">60</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5.04</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0014</span></span></span></span>；平台对成功率的主效应为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">36</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.01</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1485</span></span></span></span>。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：这套 embodiment-agnostic 流水线真的比任务专用 baseline 强吗？</strong> 实验一在三个平台（双臂 UR3、Unitree G1 人形、仿真 GR1 人形）上跑 13 个操作任务（box、ball、buttons、plate、drawer、fridge、handover、laptop、rope、dust、tray、handover easy、oven），每个任务-平台对生成并执行 30 段视频，二值判定成败，对比 ACT、RVT-LF、PerAct-LF、PerAct2。结论是 ANOVA 支持假设 H1，方法主效应显著（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0014</span></span></span></span>）。逐任务看结果并不一边倒：在 box 上 PerAct-LF 的 57% 高于本方法的 42%，在 laptop 上 PerAct2 的 12% 高于本方法的 6%；本方法的优势集中在 buttons（73%）、fridge（31%）、handover（40%）、oven（43%）这些 baseline 接近 0% 的任务上。作者摘要里&quot;achieving up to 83% success&quot;对应的是 G1 平台在 buttons 任务上的数字，不是整体均值。</p><p><strong>问题二：换本体会掉多少？</strong> 作者预期 G1 人形因为与人类中心数据对齐会最好（假设 H2）。中位数上 G1 确实最高，但 ANOVA 不显著（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1485</span></span></span></span>），作者据此拒绝了 H2，解释是任务间方差太大压过了平台效应。这是一个诚实的负结果。</p><p><strong>问题三：迭代到底值多少？</strong> 实验二在两个物理平台上各跑 10 个任务，每个任务一次实验，最多 10 次尝试。UR3 首次成功 3/10，G1 首次成功 2/10，但两者最终都达到 8/10（80%）。成功任务的平均迭代次数分别为 2.25 和 2.75，Kaplan–Meier 式生存曲线显示前三次迭代内急剧下降、第四次基本收敛。两个失败任务是 &quot;Fold the tissue&quot;（折纸巾）和 &quot;Pick the toy&quot;，都涉及可变形物体或不可恢复错误。</p><p>限制部分作者写得很直接：可变形物体不行；首次可靠性低意味着不适合时间敏感场景；生成一段 5 秒动作视频最多需要 30 秒，实时性受限。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：PhysicalAgent 把机器人操作拆成 Perceive → Plan → Reason → Act 四段，前三段全部由不需要机器人数据的基础模型承担。动作生成用的是现成的图生视频 API，输出是一段&quot;机器人应该怎么动&quot;的视频，而不是扭矩或位姿。唯一的本体相关模块是 YOLO11-Pose 加梯度提升回归器，用约 10,000 条自动标注样本、半小时采集即可训练。VLM 在每步执行后判定成败并决定是否重试，把首次 20–30% 的成功率抬到最终 80%。方法在 13 个任务上显著优于 ACT/RVT-LF/PerAct-LF/PerAct2，但跨本体差异不显著，可变形物体仍然失败。</p><p><strong>3 句话版</strong>：用通用图生视频模型当免训练的 world model 生成动作视频，用轻量 pose 回归器把视频翻译成关节指令。VLM 闭环判定成败并重试，用重复换取鲁棒性。代价是单次不可靠、每段视频最长 30 秒生成延迟、可变形物体处理不了。</p><p><strong>1 句话版</strong>：把动作生成外包给可替换的视频 API，把本体适配压缩成一个半小时能训完的回归器，再用迭代重试兜住不可靠的首次执行。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的假设是：<strong>通用图生视频模型生成的机器人运动，在关节层面是运动学可行的，因而可以被 2D 关键点回归器忠实地还原成合法指令。</strong></p><p>这个假设脆弱在于视频模型从未见过目标机器人的运动学约束。它可以画出一个视觉上流畅、但关节角超限、连杆长度不守恒、或者违反关节耦合关系的动作序列。论文自己的设计里有一个耐人寻味的痕迹：特征向量里额外加入了 12 维&quot;关节间连杆长度&quot;。这个特征只有在视频中连杆长度不稳定时才有信息量——可以推断，作者遇到过生成视频里机械臂被拉长压缩的情况，用连杆长度特征让回归器有机会校正透视和形变带来的偏差。论文没有报告生成视频的运动学可行性统计（例如有多少比例的帧对应无解的逆运动学），这是最直接缺失的证据。</p><p>支持这个假设的证据是间接的：最终 80% 的成功率说明&quot;够用&quot;。但反过来看，首次成功率只有 20–30%，而作者把这个数字归因于&quot;初始视频生成质量&quot;，这恰恰暗示大部分失败源自生成的动作本身不可执行。也就是说，论文的核心机制在 70–80% 的情况下会立刻失效，只是被迭代掩盖了。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周之内可以只验证&quot;视频→动作&quot;这一环，不需要复现整套 agentic 回路：</p><ul><li><strong>数据</strong>：任何有关节编码器和固定相机的机械臂（UR、Franka、甚至便宜的 6-DoF 桌面臂）。让它执行随机关节轨迹，同步记录相机帧和关节角，采集 30 分钟，约 5,000–10,000 条样本。</li><li><strong>实现</strong>：用预训练 YOLO-Pose 微调关键点检测（标签由相机内参 + 正向运动学投影自动生成），特征拼成&quot;关键点坐标 + 连杆长度&quot;，训 <code>HistGradientBoostingRegressor</code> 回归关节角。这部分完全按论文描述做即可，不需要 GPU 集群。</li><li><strong>测量</strong>：两条曲线。第一条是在真实录制视频上的关节角 MAE（这是回归器上限）；第二条是在图生视频模型合成的视频上，回归出的关节序列的<strong>运动学可行性</strong>——逐帧检查关节限位、逐帧检查回归轨迹的速度/加速度是否超过机器人限制、以及连杆长度在生成视频中的相对方差。</li><li><strong>判据</strong>：若真实视频上 MAE &lt; 0.1（复现论文数字）但合成视频上超限帧比例超过 30%，则支持 §9 的怀疑，说明瓶颈在视频的运动学不可行而非回归器。若合成视频上的可行性与真实视频接近，则论文的核心假设站得住。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出一个<strong>替代解释</strong>：80% 的最终成功率可能主要来自&quot;重试次数&quot;而非&quot;视频推理&quot;，也就是说，把视频生成模型换成一个不含任何语义的随机轨迹采样器，只要保留 VLM 判定 + 最多 10 次重试的回路，成功率可能也不会差太多。</p><p>具体实验：固定 VLM 闭环和适配器不变，把动作生成模块替换为三个消融——(a) 从适配器训练集里随机重放一段该机器人自己的历史轨迹；(b) 在物体位置附近做启发式的&quot;接近-闭合-抬起&quot;脚本轨迹；(c) 原始的视频生成。在同样的 10 个任务、同样 10 次上限下比较最终成功率与平均迭代次数。如果 (a) 或 (b) 也能到 60–70%，那么论文归因于&quot;video-based generative reasoning&quot;的贡献就被大幅稀释——真正起作用的是允许重试的执行回路，而不是视频里的物理先验。</p><p>论文目前的实验设计留下了这个口子：实验一（对比 baseline）是单次执行的，实验二（迭代）没有做动作生成模块的消融。两个实验的结论因此无法交叉验证。</p><p>另一个可预测的失败条件是<strong>接触密集的精细任务</strong>。论文的失败案例是折纸巾和抓玩具，都不属于&quot;关节位置画对了就能成&quot;的类别。可以预测：任何需要精确接触力、精确抓取点或形变推理的任务，这套流水线会系统性失败，因为 2D 关键点表示里根本不携带力和接触信息。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：论文把视频当成单向的中间表示——生成一次，翻译一次，成了就走，不成就重生成。这浪费了一个信息通道：机器人执行完之后的真实图像，与生成视频中对应帧之间的<strong>差异</strong>，是关于&quot;视频模型对本体动力学误判在哪里&quot;的直接监督信号。现在这个信号只被 VLM 压缩成&quot;继续/重试/重规划&quot;三个离散 token，绝大部分信息被丢掉。</p><p><strong>新的 framing</strong>：把 PhysicalAgent 从&quot;生成-执行&quot;改成&quot;生成-执行-回归到条件&quot;的在线系统辨识回路。每次执行后，用点追踪器（CoTracker/AllTracker 之类）同时提取生成视频与真实执行视频的稠密轨迹，二者之差构成一个残差场。用这个残差场去更新的不是视频模型的权重（太贵），而是喂给视频模型的<strong>条件提示</strong>与适配器的输入分布——即把&quot;这个机器人在这个场景下，视频模型会怎样系统性地高估/低估运动&quot;显式建模成一个可学习的本体偏差项。</p><p><strong>可借鉴的相邻领域</strong>：系统辨识与残差策略学习。机器人学里的 residual RL 和 sim-to-real 的 domain randomization 都在解决同一个结构问题——一个通用先验加一个本体特定的修正项。这里的新意在于修正项作用在&quot;生成条件&quot;这一层，而非动作层，因此可以在不碰视频模型参数的前提下积累经验。</p><p><strong>第一个实验</strong>：在单一平台单一任务上，记录 100 次执行的&quot;生成轨迹 vs 实际轨迹&quot;配对，拟合一个从生成轨迹到实际轨迹的低维校正映射（先试仿射，再试小 MLP）。然后在推理时把校正后的轨迹送进适配器。测量指标：首次成功率。如果首次成功率从 20–30% 提升到 45% 以上，就说明视频模型的误差是系统性的、可学习的，而不是随机的——这会把论文&quot;靠重复换鲁棒&quot;的定位改写成&quot;靠少量本体经验换单次可靠性&quot;。</p>',50)])])}const m=s(o,[["render",r]]);export{h as __pageData,m as default};
